<?php
namespace App\Http\Controllers\SupervisorPortal;
use App\Http\Controllers\Controller; use App\Http\Controllers\SupervisorPortal\Concerns\AuthorizesAssignedStudents; use App\Models\GuardianCall; use App\Models\Student; use App\Models\StudentNote; use App\Services\AuditService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Validation\Rule; use Illuminate\View\View;
class StudentNoteController extends Controller { use AuthorizesAssignedStudents; public function index(Request $r): View { $ids=$r->user()->supervisedClassrooms()->pluck('classrooms.id'); return view('supervisor.notes.index',['notes'=>StudentNote::with('student.user')->whereHas('student',fn($q)=>$q->whereIn('classroom_id',$ids))->latest()->paginate(30),'students'=>Student::with(['user','classroom'])->whereIn('classroom_id',$ids)->where('status','active')->get()]); } public function storeDirect(Request $r): RedirectResponse { $r->validate(['student_id'=>['required','integer','exists:students,id']]); return $this->store($r,Student::findOrFail($r->integer('student_id'))); } public function store(Request $r,Student $student): RedirectResponse { $this->authorizeStudent($r,$student); $d=$r->validate(['type'=>['required',Rule::in(['general','health','psychological','behavioral','administrative'])],'title'=>['required','string','max:255'],'content'=>['required','string','max:5000'],'visibility'=>['required',Rule::in(['internal','guardian'])],'requires_guardian_call'=>['nullable','boolean']]); $note=StudentNote::create($d+['student_id'=>$student->id,'supervisor_id'=>$r->user()->id]); AuditService::record('created','student_notes',$note); if($note->requires_guardian_call){$call=GuardianCall::create(['student_id'=>$student->id,'supervisor_id'=>$r->user()->id,'student_note_id'=>$note->id,'category'=>$note->type,'reason'=>$note->title,'details'=>$note->content,'guardian_visible_details'=>$note->visibility==='guardian'?$note->content:null,'status'=>'pending','requested_date'=>today()]); AuditService::record('created','guardian_calls',$call);} return back()->with('success','تم حفظ ملاحظة المتابعة.'); } }
